{
  "name": "BACnet MS/TP总线通信接口",
  "name_en": "BACnet MS/TP Bus Communication Interface",
  "manufacturer": "",
  "description": "一种用于BACnet MS/TP现场总线通信的接口或网络节点，通常连接楼宇自动化控制器、传感器和执行器，在RS-485类总线上收发并转发报文。实验室中可用于楼宇自控网络联调、设备发现、属性读写和总线通信测试。",
  "description_en": "A communication interface or network node for BACnet MS/TP fieldbus networks, typically linking building automation controllers, sensors, and actuators while sending, receiving, and forwarding messages on an RS-485-style bus. In the lab, it can be used for building automation network integration, device discovery, property read/write testing, and bus communication validation.",
  "tag_hints": [
    "BACnet MS/TP",
    "building automation",
    "RS-485 field bus",
    "device discovery",
    "property read/write",
    "network message routing"
  ],
  "actions": [
    {
      "action_name": "auto-actor_error",
      "description": "处理某个已连接网络节点的通信错误。",
      "description_en": "Handle a communication error for a connected network node."
    },
    {
      "action_name": "auto-add_actor",
      "description": "添加新的已连接网络节点。",
      "description_en": "Add a newly connected network node."
    },
    {
      "action_name": "auto-close_socket",
      "description": "关闭通信连接。",
      "description_en": "Close the communication connection."
    },
    {
      "action_name": "auto-del_actor",
      "description": "移除已断开的网络节点。",
      "description_en": "Remove a disconnected network node."
    },
    {
      "action_name": "auto-handle_close",
      "description": "处理连接关闭事件。",
      "description_en": "Handle a connection close event."
    },
    {
      "action_name": "auto-handle_connect",
      "description": "处理新连接建立事件。",
      "description_en": "Handle a new connection event."
    },
    {
      "action_name": "auto-handle_error",
      "description": "处理通信过程中的错误。",
      "description_en": "Handle an error during communication."
    },
    {
      "action_name": "auto-handle_read",
      "description": "读取并处理收到的总线报文。",
      "description_en": "Read and process received bus messages."
    },
    {
      "action_name": "auto-handle_write",
      "description": "发送排队等待的总线报文。",
      "description_en": "Transmit queued bus messages."
    },
    {
      "action_name": "auto-indication",
      "description": "将待发送报文指示到目标节点。",
      "description_en": "Indicate an outgoing message to the target node."
    },
    {
      "action_name": "auto-readable",
      "description": "检查是否有可读取的数据。",
      "description_en": "Check whether data is available to read."
    },
    {
      "action_name": "auto-writable",
      "description": "检查是否有待发送的数据。",
      "description_en": "Check whether there is data pending to write."
    },
    {
      "action_name": "auto-atexit_handler",
      "description": "在退出时执行通信清理。",
      "description_en": "Perform communication cleanup on exit."
    },
    {
      "action_name": "auto-get_actor",
      "description": "获取指定地址对应的已连接节点。",
      "description_en": "Get the connected node associated with a specified address."
    },
    {
      "action_name": "auto-sap_indication",
      "description": "处理来自服务接入点的请求指示。",
      "description_en": "Handle a request indication from the service access point."
    },
    {
      "action_name": "auto-sap_confirmation",
      "description": "处理来自服务接入点的确认信息。",
      "description_en": "Handle a confirmation from the service access point."
    },
    {
      "action_name": "auto-confirmation",
      "description": "处理上层通信确认。",
      "description_en": "Handle an upper-layer communication confirmation."
    }
  ]
}

